using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using StockManagement.Data;using StockManagement.Models;
namespace StockManagement.Controllers;[Authorize(Roles=Roles.Admin+","+Roles.Manager)] public class ReportsController:Controller{readonly ApplicationDbContext _db;public ReportsController(ApplicationDbContext db)=>_db=db;public IActionResult Stock(){return View(_db.Products.Include(x=>x.Category).OrderBy(x=>x.CurrentStock).ToList());}public IActionResult Sales(){var from=DateTime.UtcNow.Date.AddDays(-30);ViewBag.Total=_db.Sales.Where(x=>x.SaleDate>=from).Sum(x=>(decimal?)x.TotalAmount)??0;return View(_db.Sales.Include(x=>x.Customer).Where(x=>x.SaleDate>=from).OrderByDescending(x=>x.SaleDate).ToList());}public IActionResult Purchases(){var from=DateTime.UtcNow.Date.AddDays(-30);ViewBag.Total=_db.Purchases.Where(x=>x.PurchaseDate>=from).Sum(x=>(decimal?)x.TotalAmount)??0;return View(_db.Purchases.Include(x=>x.Supplier).Where(x=>x.PurchaseDate>=from).OrderByDescending(x=>x.PurchaseDate).ToList());}}
